import React, { useEffect, useState } from "react";

import api from "../services/api";

const BookingForm = ({
  blocks,
  formData,
  onChange,
  onSubmit,
  onAvailabilityCheck,
  loading
}) => {
  const [blockId, setBlockId] = useState(formData.blockId || "");
  const [resources, setResources] = useState([]);
  const [resourceLoading, setResourceLoading] = useState(false);
  const [resourceError, setResourceError] = useState("");

  useEffect(() => {
    setBlockId(formData.blockId || "");
  }, [formData.blockId]);

  useEffect(() => {
    let isMounted = true;

    const fetchResources = async () => {
      if (!blockId) {
        setResources([]);
        setResourceError("");
        setResourceLoading(false);
        return;
      }

      setResourceLoading(true);
      setResourceError("");

      try {
        const response = await api.get(`/blocks/${blockId}/resources`);
        if (isMounted) {
          setResources(response.data);
        }
      } catch (error) {
        if (isMounted) {
          setResources([]);
          setResourceError(error.response?.data?.detail || "Could not load resources.");
        }
      } finally {
        if (isMounted) {
          setResourceLoading(false);
        }
      }
    };

    fetchResources();

    return () => {
      isMounted = false;
    };
  }, [blockId]);

  const handleBlockChange = (event) => {
    const nextBlockId = event.target.value;

    setBlockId(nextBlockId);
    onChange({
      target: {
        name: "blockId",
        value: nextBlockId
      }
    });
  };

  const handleFieldChange = (event) => {
    onChange(event);
  };

  return (
    <div className="panel-card">
      <div className="panel-header">
        <div>
          <h3>Create Booking</h3>
          <p>Choose a block, resource, date, and time slot.</p>
        </div>
      </div>

      <form className="grid-form" onSubmit={onSubmit}>
        <label>
          <span>Block</span>
          <select name="blockId" value={blockId} onChange={handleBlockChange} required>
            <option value="">Select block</option>
            {blocks.map((block) => (
              <option key={block.id} value={block.id}>
                Block {block.name}
              </option>
            ))}
          </select>
        </label>

        <label>
          <span>Resource</span>
          <select
            name="resourceId"
            value={formData.resourceId}
            onChange={handleFieldChange}
            required
            disabled={!blockId || resourceLoading}
          >
            <option value="">
              {resourceLoading ? "Loading resources..." : "Select resource"}
            </option>
            {resources.map((resource) => (
              <option key={resource.id} value={resource.id}>
                {resource.name}
              </option>
            ))}
          </select>
          {resourceLoading ? <small className="field-note">Loading resources...</small> : null}
          {!resourceLoading && blockId && resources.length === 0 && !resourceError ? (
            <small className="field-note">No resources found for this block.</small>
          ) : null}
          {resourceError ? <small className="field-note error-text">{resourceError}</small> : null}
        </label>

        <label>
          <span>Date</span>
          <input
            type="date"
            name="bookingDate"
            value={formData.bookingDate}
            onChange={handleFieldChange}
            required
          />
        </label>

        <label>
          <span>Start time</span>
          <input
            type="time"
            name="startTime"
            value={formData.startTime}
            onChange={handleFieldChange}
            required
          />
        </label>

        <label>
          <span>End time</span>
          <input
            type="time"
            name="endTime"
            value={formData.endTime}
            onChange={handleFieldChange}
            required
          />
        </label>

        <label className="full-width">
          <span>Purpose</span>
          <textarea
            name="purpose"
            value={formData.purpose}
            onChange={handleFieldChange}
            rows="4"
            placeholder="Add purpose for this booking"
          />
        </label>

        <div className="form-actions full-width">
          <button type="button" className="secondary-button" onClick={onAvailabilityCheck}>
            Check Availability
          </button>
          <button type="submit" className="primary-button" disabled={loading}>
            {loading ? "Submitting..." : "Create Booking"}
          </button>
        </div>
      </form>
    </div>
  );
};

export default BookingForm;
